"""Startup India + e-commerce policy pages shown in the footer.
Informational summaries only - always verify current rules on the official portals."""

STARTUP, ECOM = 'Startup India Policies', 'E-commerce & Legal'
SI = 'https://www.startupindia.gov.in'

POLICIES = {
 'dpiit-recognition': (STARTUP, 'DPIIT Recognition', "A startup can be recognised by the Department for Promotion of Industry and Internal Trade (DPIIT) if it is a Private Limited Company, LLP or Partnership Firm, is within 10 years of incorporation (20 years for deep-tech), has annual turnover not above Rs 200 crore (Rs 300 crore for deep-tech), works on innovation or a scalable model with job and wealth creation potential, and was not formed by splitting up an existing business. Recognition is the gateway to every Startup India benefit.\nHow to apply: register on the Startup India / National Single Window System (NSWS) portal, fill the DPIIT recognition form, upload the certificate of incorporation, PAN, business description and director details, sign with a Digital Signature Certificate, and receive the certificate, usually within days with no physical inspection.", SI),
 'seed-fund-scheme': (STARTUP, 'Startup India Seed Fund Scheme (SISFS)', "Funds early-stage startups through selected incubators for proof of concept, prototype development, product trials, market entry and commercialisation. Only DPIIT-recognised startups, generally less than 2 years old, can apply through an incubator.", SI),
 'fund-of-funds': (STARTUP, 'Fund of Funds for Startups (FFS)', "Government capital is routed through SEBI-registered Alternative Investment Funds (AIFs), which then invest in growth-stage startups. This gives startups structured equity capital without the government investing directly.", SI),
 'credit-guarantee': (STARTUP, 'Credit Guarantee Scheme (CGSS)', "Provides collateral-free loans to startups: the government gives a credit guarantee to lenders on behalf of the startup, so founders can borrow for equipment, vehicles and working capital without pledging assets.", SI),
 'tax-holiday-sec-140': (STARTUP, 'Tax Holiday - Section 140', "Eligible DPIIT-recognised startups can claim 100% exemption on profits for 3 financial years under Section 140 of the Income Tax Act 2025 (earlier Section 80-IAC), so profits can be reinvested in growth instead of being paid as tax.", SI),
 'loss-carry-forward-sec-119': (STARTUP, 'Loss Carry-Forward - Section 119', "Normally a company loses the right to carry forward tax losses if more than 51% of its shareholding changes. Section 119 of the Income Tax Act 2025 waives this restriction for recognised startups, so they can raise several equity rounds without losing accumulated loss benefits.", SI),
 'esop-deferred-tax': (STARTUP, 'ESOP Deferred Taxation', "Employees of eligible startups are taxed on ESOP perquisites at the time of sale of shares, not at exercise. This reduces the immediate tax burden and makes ESOPs a more attractive way to pay early talent.", SI),
 'companies-act-relaxations': (STARTUP, 'Companies Act Relaxations', "Recognised startups get: no cash flow statement with financial statements; annual return signable by a single director; only 1 board meeting per half-year with a 90-day gap; ESOPs to promoters and directors for up to 10 years; sweat equity up to 50% of paid-up capital for 10 years (25% for others); and member deposits without the usual 35% cap for 10 years.", SI),
 'self-certification': (STARTUP, 'Self-Certification (Labour & Environment)', "Startups can self-certify compliance under selected labour and environment laws, with no routine inspector visits during the first years of operation. This reduces regulatory burden while the business is being built.", SI),
 'ip-fast-track': (STARTUP, 'IP Protection - SIPP', "The Scheme for Facilitating Start-ups Intellectual Property Protection (SIPP) offers facilitator support and reduced fees for patent, trademark and design filings, with fast-track examination for startups.", SI),
 'gem-startup-runway': (STARTUP, 'GeM Startup Runway', "Recognised startups can register on the Government e-Marketplace (GeM) and sell directly to government buyers with relaxed prior experience and turnover requirements.", SI),
 'genesis': (STARTUP, 'GENESIS (Tier-II / III Cities)', "Supports technology startups from non-metro cities with funding and ecosystem development, promoting geographic inclusion. A strong fit for rural-first businesses like GramKart.", SI),
 'agrisure': (STARTUP, 'AgriSURE', "Funding support for agriculture and rural enterprise startups such as soil technology, precision farming and agri supply chain.", SI),
 'tide-2': (STARTUP, 'TIDE 2.0', "Financial and technical support for ICT-based startups, including hardware, software and platform innovation, delivered through incubators.", SI),
 'convertible-notes': (STARTUP, 'Convertible Notes', "A recognised startup can raise Rs 25 lakh or more through a convertible note, which converts into equity or is repayable within 10 years from issue, in a single tranche. Such money is not treated as a deposit under company law and lets early startups raise capital without fixing a valuation immediately.", SI),
 'msme-udyam': (STARTUP, 'MSME / Udyam Registration', "Startups and seller partners that qualify as MSMEs can register on the Udyam portal to access additional credit, technology and market support schemes from the Ministry of MSME.", 'https://udyamregistration.gov.in'),
 'atal-innovation-mission': (STARTUP, 'Atal Innovation Mission', "Atal Incubation Centres and Atal Tinkering Labs provide infrastructure, mentorship and seed funding to early-stage innovators across schools, colleges and communities.", 'https://aim.gov.in'),
 'mentorship-maarg': (STARTUP, 'MAARG Mentorship & Challenges', "MAARG is the government-curated national mentorship platform connecting startups with industry experts. The Bharat Startup Grand Challenge and National Startup Awards add funding prizes and visibility.", SI),
 'state-startup-policies': (STARTUP, 'State / UT Startup Policies', "Most states accept DPIIT recognition without a separate application and run their own schemes: land subsidies, power tariff concessions, state seed funds, patent fee reimbursement and employment incentives. Check your home state's startup policy (for example Gujarat iStart).", SI),
 'make-in-india': (STARTUP, 'Make in India & Local Sellers', "Manufacturing-focused businesses benefit from PLI schemes, procurement preferences and export support. GramKart lists local weavers, artisans and small manufacturers so that these benefits reach rural sellers.", 'https://www.makeinindia.com'),

 'consumer-protection': (ECOM, 'Consumer Protection (E-Commerce) Rules 2020', "Under the Consumer Protection Act 2019 and the E-Commerce Rules 2020 we display seller details, total price with all charges, return, refund and exchange terms, and country of origin. We never manipulate prices or run unfair trade practices, and we have a grievance officer who acknowledges complaints within 48 hours and resolves them within one month.", 'https://consumeraffairs.nic.in'),
 'fdi-policy': (ECOM, 'FDI Policy for E-commerce', "Under India's FDI policy, foreign investment is allowed in the marketplace model of e-commerce. A marketplace platform provides technology and does not own inventory or control prices. GramKart operates as a marketplace connecting independent sellers and buyers.", 'https://www.dpiit.gov.in'),
 'gst-ecommerce': (ECOM, 'GST for E-commerce', "E-commerce operators are required to register for GST and collect Tax Collected at Source (TCS) on sales made by sellers on the platform. Prices on GramKart include estimated GST, and a tax invoice is issued for each order.", 'https://www.gst.gov.in'),
 'privacy-dpdp': (ECOM, 'Privacy & Data Protection (DPDP Act 2023)', "We collect only the personal data needed to process orders and deliveries, ask for your consent, protect data with reasonable security safeguards, and let you correct or erase your data. This follows the Digital Personal Data Protection Act 2023 and the Information Technology Act 2000.", 'https://www.meity.gov.in'),
 'legal-metrology': (ECOM, 'Legal Metrology, FSSAI & BIS', "Pre-packaged goods must show maximum retail price, net quantity, manufacturer details and country of origin as required by Legal Metrology rules. Food items need an FSSAI licence and certain products need BIS certification. We verify seller licences before listing.", 'https://consumeraffairs.gov.in'),
 'payments-rbi': (ECOM, 'Payments & RBI Rules', "Payments are processed through RBI-authorised payment gateways supporting UPI, cards, net banking and wallets, with card data handled under PCI-DSS standards. Cash on Delivery is available on eligible pin codes, including rural areas.", 'https://www.rbi.org.in'),
 'ondc': (ECOM, 'ONDC - Open Network for Digital Commerce', "ONDC is an open, interoperable network that lets buyers and sellers transact across different apps. Joining ONDC is on our roadmap to widen choice for rural customers and small sellers.", 'https://ondc.org'),
 'shipping-policy': (ECOM, 'Shipping & Delivery Policy', "We deliver across India, including rural pin codes, through city warehouses, district hubs and village delivery partners (Gram Mitras). Standard delivery takes 3-7 business days (rural areas may take up to 7), express 1-3 days. Delivery is free on orders over Rs 999; otherwise a flat Rs 79 applies. Orders are confirmed with an OTP on delivery.", None),
 'returns-refunds': (ECOM, 'Returns & Refund Policy', "Unused items with tags can be returned within 7 days of delivery. Return pickup is arranged from your village delivery partner. Refunds go to the original payment method within 5-7 business days after the item passes quality check; Cash on Delivery orders are refunded by bank or UPI transfer.", None),
 'terms-of-use': (ECOM, 'Terms of Use', "By using GramKart you agree to provide accurate information, not misuse the platform, and accept our shipping, return and privacy policies. Prices and availability may change without notice. These terms are governed by the laws of India.", None),
 'grievance-officer': (ECOM, 'Grievance Officer', "As required by the Consumer Protection (E-Commerce) Rules 2020 and the IT Rules, our Grievance Officer can be contacted at grievance@gramkart.in (placeholder - replace with your real details). Complaints are acknowledged within 48 hours and resolved within one month.", None),
}

def grouped():
    out = {STARTUP: [], ECOM: []}
    for slug, (g, title, *_ ) in POLICIES.items():
        out[g].append((slug, title))
    return out
